# Group priority, top to bottom: Admin > Friend > Guest > Visitor.
# An empty password means "open to everyone", so every group below an open
# group can never be reached. Therefore:
#   1. Once a password is empty, all passwords below it must be empty too (else error).
#   2. Only the topmost empty group is written to the config, the groups below are removed.
def groups: [
  {"name": "Admin",   "password": "${adminPassword}"},
  {"name": "Friend",  "password": "${friendPassword}"},
  {"name": "Guest",   "password": "${guestPassword}"},
  {"name": "Visitor", "password": "${visitorPassword}"}
];

# Position of the topmost group with an empty password, null if every group has one.
def open_index: groups | map(.password == "") | index(true);

# Rule 1: abort if a group below the open group still has a password.
def validate:
  open_index as $i
  | if $i != null and (groups | .[$i + 1:] | any(.password != ""))
    then error("Group passwords: " + groups[$i].name + " is empty, so all groups below it must be empty too")
    else . end;

# Rule 2: update, create or (below the open group) remove one group.
# Other groups and the permissions of existing groups are left untouched.
def apply($g; $below_open):
  if $below_open then .userGroups |= map(select(.name != $g.name))
  elif any(.userGroups[]; .name == $g.name) then .userGroups |= map(if .name == $g.name then .password = $g.password else . end)
  else .userGroups += [$g] end;

validate
| open_index as $open
| .name = "${serverName}"
| .queryPort = ${queryPort}
| .slotCount = ${slotCount}
| .enableVoiceChat = ${enableVoiceChat}
| .enableTextChat = ${enableTextChat}
| .gameSettingsPreset = "${gameSettingsPreset}"
| .userGroups //= []
| reduce (groups | to_entries[]) as {key: $n, value: $g} (.; apply($g; $open != null and $n > $open))
